import 'jsr:@supabase/functions-js/edge-runtime.d.ts';
import { createClient } from 'jsr:@supabase/supabase-js@2';
import { smsServiceLabelEn, smsVenueLocationForReminder } from './sms-labels.ts';

// Comment: Shared 3-day reminder SMS — keep in sync with `lib/booking-reminder-sms.ts`.

const WEEKDAY_SHORT = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'] as const;

/** dd/mm (Sat) 11:00am — calendar date + wall time from stored booking_date + booking_time. */
function formatReminderAppointmentLine(bookingDate: string, bookingTime: string | null): string {
  try {
    const [year, month, day] = bookingDate.split('-').map((v) => Number(v));
    const [hStr, mStr] = (bookingTime ?? '00:00:00').split(':');
    const hour = Number(hStr);
    const minute = Number(mStr);
    const date = new Date(Date.UTC(year, month - 1, day, hour, minute));
    const dd = String(day).padStart(2, '0');
    const mm = String(month).padStart(2, '0');
    const dow = WEEKDAY_SHORT[date.getUTCDay()];
    let displayHour = date.getUTCHours();
    const displayMinute = String(date.getUTCMinutes()).padStart(2, '0');
    const ampm = displayHour >= 12 ? 'pm' : 'am';
    displayHour = displayHour % 12;
    if (displayHour === 0) displayHour = 12;
    return `${dd}/${mm} (${dow}) ${displayHour}:${displayMinute}${ampm}`;
  } catch {
    return `${bookingDate} ${bookingTime ?? ''}`.trim();
  }
}

function buildBookingReminderSmsBody(params: {
  appointmentLine: string;
  serviceLabel: string;
  shopLocation: string;
  shopPhone?: string | null;
}): string {
  const contactPhone = String(params.shopPhone ?? '').trim() || '0432 328 002';
  const loc = String(params.shopLocation ?? '').trim() || 'Haeyoom salon';

  return (
    `[Haeyoom Reminder]\n\n` +
    `Booking:\n` +
    `${params.appointmentLine}\n\n` +
    `Service: ${params.serviceLabel}\n\n` +
    `Change or Cancel:\n` +
    `Call or Text\n` +
    `${contactPhone}\n\n` +
    `Location: ${loc}`
  );
}

const supabaseUrl = Deno.env.get('SUPABASE_URL');
const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');

if (!supabaseUrl || !supabaseServiceKey) {
  throw new Error('Missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY environment variables');
}

const supabase = createClient(supabaseUrl, supabaseServiceKey, {
  auth: { persistSession: false },
});

const MOBILE_MESSAGE_API_USERNAME = Deno.env.get('MOBILE_MESSAGE_API_USERNAME') ?? '';
const MOBILE_MESSAGE_API_PASSWORD = Deno.env.get('MOBILE_MESSAGE_API_PASSWORD') ?? '';
const MOBILE_MESSAGE_SENDER_ID = Deno.env.get('MOBILE_MESSAGE_SENDER_ID') ?? '';

function toAuMobileRecipient(phone: string): string {
  const digits = phone.replace(/\D/g, '');
  if (digits.startsWith('61') && digits.length === 11) {
    return `0${digits.slice(2)}`;
  }
  if (digits.startsWith('0') && digits.length === 10) {
    return digits;
  }
  return phone.trim();
}

async function sendSmsViaMobileMessage(to: string, body: string): Promise<Response> {
  const basicAuth = btoa(`${MOBILE_MESSAGE_API_USERNAME}:${MOBILE_MESSAGE_API_PASSWORD}`);
  return await fetch('https://api.mobilemessage.com.au/v1/messages', {
    method: 'POST',
    headers: {
      Authorization: `Basic ${basicAuth}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      messages: [
        {
          to: toAuMobileRecipient(to),
          message: body,
          sender: MOBILE_MESSAGE_SENDER_ID,
        },
      ],
    }),
  });
}

function formatDate(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function getSydneyFutureDateString(daysAhead: number): string {
  const now = new Date();
  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Australia/Sydney',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  });

  const todaySydneyStr = formatter.format(now);
  const [year, month, day] = todaySydneyStr.split('-').map(Number);
  const futureSydney = new Date(year, month - 1, day + daysAhead);
  return formatDate(futureSydney);
}

function getSydneyHourMinuteNow(): { hour: number; minute: number } {
  const now = new Date();
  const sydneyTime = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Australia/Sydney',
    hour12: false,
    hour: '2-digit',
    minute: '2-digit',
  }).format(now);
  const [h, m] = sydneyTime.split(':').map(Number);
  return { hour: h, minute: m };
}

Deno.serve(async (_req: Request) => {
  try {
    console.log('[booking-reminder] function triggered');

    if (!MOBILE_MESSAGE_API_USERNAME || !MOBILE_MESSAGE_API_PASSWORD || !MOBILE_MESSAGE_SENDER_ID) {
      console.error('[booking-reminder] Mobile Message env missing');
      return new Response(JSON.stringify({ error: 'SMS provider not configured' }), {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    const { hour, minute } = getSydneyHourMinuteNow();
    // Comment: Only run at exactly 14:30 Sydney (daily cron must fire in that minute).
    const atSydney1430 = hour === 14 && minute === 30;
    if (!atSydney1430) {
      console.log(
        `[booking-reminder] Skip run outside 14:30 Sydney (current ${hour}:${String(minute).padStart(2, '0')}).`,
      );
      return new Response(JSON.stringify({ status: 'ok', sent: 0, skipped: true, reason: 'outside_1430_sydney' }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    const targetDateStr = getSydneyFutureDateString(3);

    const { data: bookings, error } = await supabase
      .from('bookings')
      .select(
        'id, booking_date, booking_time, custom_service_name, status, confirmation_sent_at, confirmed_at, customer:customer_id ( id, name, phone ), service:service_id ( name, english_name ), shop:shop_id ( name, location, phone )',
      )
      .eq('booking_date', targetDateStr)
      .in('status', ['pending', 'confirmed', 'PENDING', 'CONFIRMED', 'BOOKED', 'booked'])
      .is('confirmation_sent_at', null);

    if (error) {
      console.error('[booking-reminder] Error fetching bookings:', error);
      return new Response(JSON.stringify({ error: 'failed to fetch bookings' }), {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    if (!bookings || bookings.length === 0) {
      console.log('[booking-reminder] No bookings to send reminders for.');
      return new Response(JSON.stringify({ status: 'ok', sent: 0, targetDate: targetDateStr }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    let sentCount = 0;

    for (const booking of bookings as Record<string, unknown>[]) {
      const customer = booking.customer as { phone?: string | null } | null;
      const customerPhone = customer?.phone ?? null;

      if (!customerPhone) {
        console.warn(`[booking-reminder] Booking ${booking.id} has no customer phone. Skipping.`);
        continue;
      }

      const service = booking.service as { name?: string | null; english_name?: string | null } | null;
      const shop = booking.shop as { name?: string; location?: string | null; phone?: string | null } | null;

      const bookingDate = String(booking.booking_date ?? '');
      const bookingTime = (booking.booking_time as string | null) ?? null;
      const appointmentLine = formatReminderAppointmentLine(bookingDate, bookingTime);
      const serviceLabel = smsServiceLabelEn(
        service?.english_name,
        service?.name,
        booking.custom_service_name as string | null | undefined,
      );

      const messageBody = buildBookingReminderSmsBody({
        appointmentLine,
        serviceLabel,
        shopLocation: smsVenueLocationForReminder(shop?.location ?? '', shop?.name),
        shopPhone: shop?.phone ?? null,
      });

      const smsRes = await sendSmsViaMobileMessage(customerPhone, messageBody);
      if (!smsRes.ok) {
        const text = await smsRes.text();
        console.error(`[booking-reminder] Mobile Message error for booking ${booking.id}:`, smsRes.status, text);
        continue;
      }

      sentCount += 1;

      const { error: updateError } = await supabase
        .from('bookings')
        .update({ confirmation_sent_at: new Date().toISOString() })
        .eq('id', booking.id);

      if (updateError) {
        console.error(`[booking-reminder] Failed to update confirmation_sent_at for booking ${booking.id}:`, updateError);
      }
    }

    return new Response(JSON.stringify({ status: 'ok', sent: sentCount, targetDate: targetDateStr }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    });
  } catch (err) {
    console.error('[booking-reminder] Unexpected error:', err);
    return new Response(JSON.stringify({ error: 'internal error' }), {
      status: 500,
      headers: { 'Content-Type': 'application/json' },
    });
  }
});

/** Keep in sync with lib/public-booking-labels.ts (SMS English helpers). */

/** Exact phrase matches (after stripping card/cash suffixes and trimming). */
